import { readFileSync } from "node:fs"
import { resolve } from "node:path"
import { describe, expect, it } from "vitest"

import { buildLegacyBuildertrendReconciliationSql } from "../legacy-reconciliation"
import { parseBuildertrendStagingManifest } from "../rules"
import { buildBuildertrendStagingSql } from "../staging"

/*
 * SQL equivalence: the golden fixtures were generated by the generators in
 * src/lib/buildertrend/ before they moved behind this domain module. Staging
 * is legal-hold evidence, so the emitted SQL must stay byte-identical.
 */

function fixture(name: string): unknown {
  return JSON.parse(
    readFileSync(resolve(__dirname, "fixtures", name), "utf8")
  )
}

type StagingCase = {
  readonly name: string
  readonly organizationId: string
  readonly manifest: unknown
}

function stagingCases(): readonly StagingCase[] {
  const value = fixture("staging-cases.json")
  if (!Array.isArray(value)) throw new Error("staging-cases.json must be an array")
  return value.map((entry: unknown) => {
    if (typeof entry !== "object" || entry === null) throw new Error("bad case")
    const name = Reflect.get(entry, "name")
    const organizationId = Reflect.get(entry, "organizationId")
    if (typeof name !== "string" || typeof organizationId !== "string") {
      throw new Error("bad case")
    }
    return { name, organizationId, manifest: Reflect.get(entry, "manifest") }
  })
}

describe("Buildertrend staging SQL equivalence", () => {
  it("emits the same staging import SQL as before the move", async () => {
    const outputs = []
    for (const testCase of stagingCases()) {
      const parsed = parseBuildertrendStagingManifest(testCase.manifest)
      if (!parsed.success) throw new Error(parsed.errors.join("\n"))
      const build = await buildBuildertrendStagingSql(
        testCase.organizationId,
        parsed.data
      )
      outputs.push({ name: testCase.name, ...build })
    }
    expect(JSON.parse(JSON.stringify(outputs))).toEqual(
      fixture("staging-golden.json")
    )
  })

  it("emits the same legacy reconciliation SQL as before the move", () => {
    expect({
      "org-1": buildLegacyBuildertrendReconciliationSql("org-1"),
      "o'rg": buildLegacyBuildertrendReconciliationSql(" o'rg "),
    }).toEqual(fixture("legacy-golden.json"))
  })
})
